#include <queue>

using namespace std;

class Solution {
public:
    int maximumScore(int a, int b, int c) {
        priority_queue<int> pq;
        pq.push(a); pq.push(b); pq.push(c);
        int score = 0;
        while (true) {
            int x = pq.top(); pq.pop();
            int y = pq.top(); pq.pop();
            if (x == 0 || y == 0) break;
            x--; y--; score++;
            pq.push(x); pq.push(y);
        }
        return score;
    }
};
